custom_css:
/*票根-乱世佳人by烤冷面大王*/
/*
🌟先看这里！
气泡分为上中下，中部分了char和u两个部分
时间戳+名字也分了char和u两个部分
🌟依旧是看🌷部分自改，三元素、姓名+时间戳在最后面
切页一些地方乱了是正常的！！！
🌟🌟🌟自带纯白背景，如果要换背景（先删带🧊部分代码才可以换），千万不要用深色背景，不然会后悔的orz
*/

/* ====== 全局字体与变量 ====== */
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fbold.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A700%3Bfont-display%3Aswap%3B%7D%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");
@import url("https://fontsapi.zeoseven.com/237/main/result.css"); /* 香萃打字机体 */
@import url("https://fontsapi.zeoseven.com/309/main/result.css"); /* KingHwaOldSong */

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
} 
/* 英文专用 ZSFT-bo */
#send_textarea,#chat .mes .mes_reasoning_header,
.message-content,
.bubble-content,
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  font-family: "ZSFT-bo", "KingHwaOldSong", sans-serif !important;
}

/*变量*/
:root {
    /* 贴图变量 */
    --sctt: url('https://i.postimg.cc/pXqTC9zj/IMG-4937.png');/*上层贴图*/
    --zctt: url('https://i.postimg.cc/XYVvJpxt/IMG-4959.png');/*中层贴图*/
    --dctt: url('https://i.postimg.cc/FKqGLsDM/IMG-4939.png');/*底层贴图*/

    /* Logo 图标变量 */
    --logo1: url('https://i.postimg.cc/ZK3m9Gnk/IMG-4919.png');
    --logo2: url('https://i.postimg.cc/Jnvw0xCg/IMG-4920.png');
    --logo3: url('https://i.postimg.cc/4dKMDcH9/IMG-4921.png');
}

/*===顶栏部分===*/
#top-bar {
    position: fixed !important;
    top: 0;
    left: 0;
    width: 390px;
    height: 40px;
    background: #ffffff !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    pointer-events: none;
}

#top-bar::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 120%;
    background: #ffffff no-repeat center / cover; 
    background-color: #ffffff !important;
    z-index: 7;
    pointer-events: auto;
}

#top-bar::after {
    content: "";
    position: fixed;
    top: -65px;
    right: 80px;
    width: 260px;
    height: 200px;
    background: transparent !important;
    z-index: 8;
    pointer-events: none;
}

/*图标替换by墨千尾老师*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}

#top-settings-holder .drawer { flex: 1; }

#top-settings-holder .drawer-icon {
    display: block;
    margin-top: 15px;
    background-color: transparent;
    border-radius: 15px !important;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 25px;
    height: 25px;
    opacity: 1 !important;
}

.drawer-icon.fa-fw:hover { transform: translateY(-1.5px); }

.drawer-icon.fa-sliders,
.drawer-icon.fa-user-cog,
.drawer-icon.fa-address-card,
.drawer-icon.fa-font,
.drawer-icon.fa-cubes,
.drawer-icon.fa-plug,
.drawer-icon.fa-plug-circle-exclamation,
.drawer-icon.fa-book-atlas,
.drawer-icon.fa-panorama,
.drawer-icon.fa-face-smile {
    background-image: var(--logo1) !important;
}

/* 展开图标*/
#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: var(--logo2) !important;
    transform: scale(1.2);
}

/*底栏*/
#send_form {
    margin-bottom: 2px;
    width: 100%;
    background: #fff !important;
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;
    border-radius: 8px !important;
    border: 1px solid transparent !important;
    padding: 8px;
}

/* 输入框样式 */
#send_textarea {
    border-radius: 6px !important;
    clip-path: none !important;
    background-color: #ebebeb !important;
    border-color: transparent !important;
}

/* ===== 输入框提示文字自定义 ===== */
#nonQRFormItems {
    position: relative;
}
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "I loved something I made up.";/*🌷输入框自定义文字*/
    background: linear-gradient(to right, #333, #999);
    -webkit-background-clip: text;
    color: transparent;
    position: absolute; 
    left: 55%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.45em; 
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}

/* --- 底部按键图标替换 --- */
#options_button::before, #extensionsMenuButton::before, #send_but::before, #quick-reply-rocket-button > i { display: none !important; }
#options_button, #extensionsMenuButton, #send_but, #quick-reply-rocket-button {
    width: 25px !important;
    height: 40px !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border-radius: 0px !important;
    opacity: 1 !important;
}
#options_button, #extensionsMenuButton{ background-image: var(--logo1); }
#send_but { background-image: var(--logo1); }
#quick-reply-rocket-button { background-image: var(--logo1); }



/*🧊聊天背景*/
#sheld {
  background-color: #ffffff;
  background-image: none;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}


/*————气泡————*/
.mes {
    width: 390px !important;
    padding: 40px 12px;
    margin-bottom: 125px!important;
    margin-top: 105px!important;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: rgba(255, 255, 255, 0) !important;
    border:none!important;
    border-radius: 0;    
    box-shadow: none;    
    position: relative;
    overflow: visible !important;
}

/* 上层装饰 */
.mes::after {
    content: "";
    position: absolute; 
    left: 193px;/*🌷左右*/
    transform: translateX(-50%);
    top: -90px;
    width: 390px;/*🌷宽，没变化就改height*/
    height: 580px;
    background-image: var(--sctt);
    background-size: cover;
    background-repeat: no-repeat;
    opacity: 1 !important;
    pointer-events: none;
    z-index: 99;
}

/* 底部装饰 */
.mes::before {
    content: "";
    position: absolute;
    left: 193px;/*🌷左右*/
    transform: translateX(calc(-50% + 0px));
    bottom: -57px;/*🌷上下*/
    width: 389px;/*🌷宽，没变化就改height*/
    height: 158px;
    background: var(--dctt);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center 50%;
    opacity: 1 !important;
    pointer-events: none;
    z-index: 99;
}

/*中间 - 公共样式*/
.mes_block {
    width: 393px !important;
    max-width: none !important;
    background: transparent !important;
    background-repeat: repeat-y !important;
    background-size: 390px auto !important;
    background-position: 0px 0 !important;
    border-radius: 0 !important;
    padding: 440px 8px 5px 12px !important;/*🌷文字边距*/
    position: relative !important;
    margin-top: 0 !important;
    min-height: 100px;
    overflow: visible !important;
    z-index: 1 !important;
}

/* 中层背景：char*/
.mes:not([is_user="true"]) .mes_block::before {
    content: '' !important;
    position: absolute !important;
    left: 0 !important;
    top: 400px !important;/*🌷char气泡中部上下*/
    width: 389px !important;
    height: calc(100% - 460px) !important;
    background: var(--zctt) !important;
    background-repeat: repeat-y !important;
    background-size: 100% auto !important;
    z-index: -1 !important;
}

/* 中层背景：user*/
.mes[is_user="true"] .mes_block::before {
    content: '' !important;
    position: absolute !important;
    left: 0 !important;
    top: 420px !important;/*🌷user气泡中部上下*/
    width: 389px !important;
    height: calc(100% - 460px) !important;
    background: var(--zctt) !important;
    background-repeat: repeat-y !important;
    background-size: 100% auto !important;
    z-index: -1 !important;

}




/* 文本框与下一个头像框隔开 */
.mes {
    margin-bottom: 13em !important; 
    clear: both !important; 
}


/*文字铺满by墨千尾老师*/
.mes .mes_text {
    width: 100%;
    padding: 0px 0px 0px 0px;
    margin: 0px 0px 30px 0px;
}



/*---文字样式 ---*/
.mes {
    color: #000 !important;
}

/* 引用文本 */
.mes q {
    background: #f1f1f1 !important;
    color: #000 !important;
    border: 1px solid #ccc !important;
    padding: 5px 10px !important;
    font-style: normal !important;
    border-radius: 4px !important;
    box-shadow: none !important;
    display: inline-block !important;
}

/* 斜体文本 */
.mes i,
.mes em {
    color: #666 !important;
    text-decoration: underline !important;
}

/* 下划线文本 */
.mes u {
    text-decoration: none !important;
    color: #000 !important;
    font-weight: bold !important;
    padding: 3px 6px !important;
    border-radius: 4px !important;
    background: #e5e5e5 !important;
    border-bottom: none !important;
}



/*——思维链——*/
#chat .mes .mes_reasoning_header {
    position: relative;
  /*🌷思维链位置⬇️*/
    margin-top: -80px !important;
    margin-left: 0px !important;
}

.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;
    --bottom-padding: 1rem;
    --left-padding: 0.1rem;
    --right-padding: 0.1rem;
    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/* 来自12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0;
    backdrop-filter: none !important; 
    -webkit-backdrop-filter: none !important; 
    padding: 0 !important;
    margin-bottom: 0 !important;
    color: #000 !important; 
    font-size: 1em !important;
    display: inline-flex !important;
    align-items: center !important;
    transition: none !important; 
}
/*来自hy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}
/*来自N老师*/
.mes_reasoning_header_title::before {
    content: "" !important;

  /*🌷思维链大小⬇️*/
    width: 20px !important;
    height: 20px !important;


    background-image: var(--logo2) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    display: inline-block !important;
    vertical-align: middle !important;
}
.mes_reasoning_header_title {
    font-size: 0 !important;
}
.mes_reasoning_header_title::after {
    content: "Tomorrow is another day." !important;/*🌷思维链自定义文字*/
    font-size: 14px !important;
    color: #000 !important;
    margin-left: 6px !important;
    vertical-align: middle !important;
}


/*——图标统一替换——*/
/* 小铅笔 */
.fa-pencil-alt::before, .fa-pencil::before {
    display: none !important;
}
.fa-pencil-alt, .fa-pencil {
    background: var(--logo2) no-repeat center/contain !important;
    width: 25px !important;
    height: 25px !important;
    display: inline-block;
    vertical-align: middle;
    opacity: 1 !important;
    transition: opacity 0.3s ease !important;
}

/* 三个点 */
.fa-ellipsis-h::before, .fa-ellipsis::before {
    display: none !important;
}
.fa-ellipsis-h, .fa-ellipsis {
    background: var(--logo1) no-repeat center/contain !important;
    width: 25px !important;
    height: 25px !important;
    display: inline-block;
    vertical-align: middle;
    opacity: 1 !important;
    transition: opacity 0.3s ease !important;
}

.fa-pencil-alt:hover, 
.fa-pencil:hover, 
.fa-ellipsis-h:hover, 
.fa-ellipsis:hover {
    opacity: 1 !important;
}

/*滑块图标*/
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 25px;
    background: transparent var(--logo2) center/cover no-repeat;
    border: none;
    border-radius: 0;
    box-shadow: none;
    cursor: ew-resize;
    position: relative;
    z-index: 1;
    opacity: 1 !important;
    filter: brightness(1.2) saturate(2) !important;
    -webkit-filter: brightness(1.2) saturate(2) !important;
    background-blend-mode: normal !important;
}

/*预设编辑*/
.neo-range-slider {
    height: 3px !important;
    background: #ccc !important;
    box-shadow: inset 0 0 3px #aaa !important;
    cursor: ew-resize !important;
    z-index: 1;
    margin-bottom: 0px !important;
    border-radius: 0px !important;
}

.prompt-manager-edit-action::before {
    display: none !important;
}
.prompt-manager-edit-action {
    background: var(--logo2) no-repeat center/20px 30px !important;
    width: 25px !important;
    height: 25px !important;
    opacity: 1 !important;
}

/*编辑按钮位置*/
.mes_buttons {
    position: relative;
    top: 0px;
    left: -10px;
}

/*===来自12老师，收藏区左右滑动===*/
/* 收藏角色栏 */
#HotSwapWrapper {
    overflow: hidden;
}
#HotSwapWrapper > div {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    height: calc(var(--avatar-base-height) + 10px);
}

body.big-avatars #HotSwapWrapper > div {
    height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
#HotSwapWrapper > div::-webkit-scrollbar {
    height: 5px; 
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
    background-color: #000 !important; 
    border-radius: 5px; 
}

/* 收藏角色边框 黑色 */
.character_select.is_fav .avatar {
    outline: 2px solid #000 !important;
}

/* 收藏角色名字 黑色高亮 */
.character_select.is_fav .ch_name {
    color: #000 !important;
    text-shadow: 0 0 4px #fff, 0 0 8px #aaa !important;
}

/*来自12老师，拉进最后一条消息头像与名字距离*/
.mes .mesAvatarWrapper {
    padding: 0 !important;
}

/*——切页——*/
.swipe_left::before, .swipe_right::before { content: '' !important; }
.swipe_left:hover, .swipe_right:hover { transform: scale(1.1); }
.swipes-counter { 
    color: #000 !important; 
    opacity: 1 !important; 
    transform: translateY(130px) !important;
}

.swipe_right, .swipe_left {
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: transform 0.2s ease;
    width: 20px;
    height: 30px;
    transform: translateY(70px) !important;
    background-color: transparent !important;
}

.swipe_right, .swipe_left {
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: transform 0.2s ease;
    width: 20px;
    height: 30px;
    transform: translateY(120px) !important;
    background-color: transparent !important;
}

.swipe_right { background-image: var(--logo1) !important; }
.swipe_left { background-image: var(--logo1) !important;}


/* --- 折叠面板按键 --- */
.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 24px !important; 
    height: 24px !important; 
    background: transparent !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer;
    filter: none !important; 
    opacity: 1 !important; 
    color: #000 !important; 
    border: none !important; 
    box-shadow: none !important; 
}

.inline-drawer-icon::before {
    content: "" !important;
    display: block !important;
    background-image: var(--logo3) !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    width: 25px !important;
    height: 39px !important;
    color: transparent !important;

    opacity: 1 !important; 
    text-shadow: none !important; 
}

.inline-drawer-icon:hover::before {
    transform: scale(1.2) !important;
    filter: grayscale(1) brightness(0.2) !important; 
}

/* 来自deleted user老师，加载动画 */
#preloader {
    position: fixed;
    margin: 0;
    padding: 0;
    top: 0;
    left: 0;
    z-index: 999999;
    width: 100vw;
    height: 100vh;
    background-color: #fff; 
    opacity: 1;
}

#load-spinner {
    --spinner-size: 85px;
    transition: none !important;
    opacity: 1 !important;
    top: calc(50% - var(--spinner-size) / 2);
    left: calc(50% - var(--spinner-size) / 2);
    position: absolute;
    width: var(--spinner-size);
    height: var(--spinner-size);
    background-image: var(--logo1) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    animation: moon-breath 3s ease-in-out infinite !important;
    transform: none !important;
}

@keyframes heartbeat {
    0%, 100% { transform: scale(1); opacity: 1; }
    15% { transform: scale(1.2); opacity: 0.9; }
    30% { transform: scale(1); opacity: 1; }
    45% { transform: scale(1.2); opacity: 0.9; }
    60% { transform: scale(1); opacity: 1; }
}

#load-spinner::before,
#load-spinner::after {
    display: none !important;
}


/*提示词管理*/
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    color: #000 !important;
    background: #f5f5f5 !important;
    background-size: 100%;
    border-radius: 1px 1px 12px 12px;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    border-radius: 15px !important;
    padding: 5px !important;
}
.completion_prompt_manager_prompt .fa-asterisk,
.completion_prompt_manager_prompt .fa-square-poll-horizontal,
.completion_prompt_manager_prompt .fa-syringe,
.completion_prompt_manager_prompt .fa-thumb-tack,
.fa-xs.fa-solid.fa-robot {
    color: #000 !important;
}
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #000 !important;
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span,
#completion_prompt_manager .completion_prompt_manager_header div,
.prompt_manager_prompt_controls span {
    filter: none !important;
    color: #000 !important;
}
.inline-drawer-header .inline-drawer-icon {
    color: #000 !important;
    transform: scale(0.8);
}

/* 预设底板 */
#completion_prompt_manager, 
#completion_prompt_manager_list {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    background: #fff center/cover !important;
    border-color: #333 !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt:hover {
    background: rgba(220,220,220,0.5) !important;
    background-size: cover !important; 
    background-position: center !important; 
    border-color: #000 !important;
    transform: translateY(-2px); 
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1) !important;
    cursor: pointer;
}

/* ===== 通用 UI 组件 ===== */
.menu_button, .right_menu_button {
    background-color: #fff !important;
    color: #333 !important;
    border: 1px solid #333 !important;
    border-radius: 10px !important;
    transition: background-color 0.3s ease, transform 0.2s ease !important;
}

.menu_button:hover, .right_menu_button:hover {
    color: #fff !important;
    background-color: #333 !important;
    transform: translateY(-2px);
}

.avatar-container.interactable.selected {
    background: #fff !important;
    background-size: cover;
    border: 1px solid #333 !important;
}

.text_pole, select, input[type="text"], input[type="number"], input[type="search"], 
#settingsSearch, .popup textarea, #description_textarea, #firstmessage_textarea, 
.edit_textarea.mdHotkeys, .reasoning_edit_textarea, 
.select2-container--default .select2-selection--single, 
.select2-container--default .select2-selection--multiple {
    background-color: #fff !important;
    padding: 1px !important;
    border-radius: 10px !important;
    border: 1px solid #000 !important;
}

::selection { background: #333; color: #fff; }

dialog.popup, #select_chat_popup, select, .list-group, .select2-dropdown, 
#options, #options-content, #extensionsMenu { box-shadow: none !important; }

.select2-selection__choice { 
    background-color: #fff !important; 
    border: 1px solid #333 !important; 
}
.select2-selection__choice__display, .select2-selection__choice__remove { 
    background: none !important; 
    color: #000 !important;
}


/* 来自咩咩咩咩咩咩野老师，全局隐藏 Webkit 系浏览器的滚动条 */
::-webkit-scrollbar {
  display: none;
}

/* Firefox 全局滚动条样式 */
html {
  scrollbar-width: thin; /* auto | thin | none */
  scrollbar-color: #888 #f1f1f1; /* 滑块颜色 轨道颜色 */
}


/* 去阴影 */
.fa-pencil-alt,
.fa-pencil,
.fa-ellipsis-h,
.fa-ellipsis,
.fa-pencil-alt:hover,
.fa-pencil:hover,
.fa-ellipsis-h:hover,
.fa-ellipsis:hover {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
  border: none !important;
  outline: none !important;
  background-color: transparent !important;
}
/* 去阴影，小眼睛、小星星 */
.menu_button, .fa-eye, .fa-ranking-star {
    text-shadow: none !important;
    box-shadow: none !important;
    filter: none !important; 
}




/*哈基米赞助去阴影别动！*/
/* 1. 彻底清除所有图标的文字阴影 */
.fa-solid, .fa-regular, .fa-brands, i {
    text-shadow: none !important;
    filter: none !important;
}

/* 2. 针对圆形按钮容器*/
.menu_button, .drawer-content i, .fa-button {
    box-shadow: none !importan;
    border: none !important;
}

/* 3. 针对列表图标容器 */
#show_main_menu, #show_extensions_menu {
    box-shadow: none !important;
    text-shadow: none !important;
}

/* 4. 强制取消所有可能导致阴影的滤镜 */
* {
    --box-shadow: none !important;
    --text-shadow: none !important;
}





